// ✅ VALIDACIÓN DE DATOS v2.0
const webhookData = $json;

console.log('🎯 Webhook v2.0 data received');

// Extraer datos del body
const bodyData = webhookData.body || webhookData;
const actions = bodyData.actions || [];
const metadata = bodyData.metadata || {};
const sessionId = bodyData.sessionId || `session-${Date.now()}`;

console.log(`📊 Found ${actions.length} actions`);
console.log('📊 Actions:', JSON.stringify(actions, null, 2));

// Validación
if (!Array.isArray(actions) || actions.length === 0) {
  console.log('❌ No valid actions found');
  return [{
    json: {
      success: false,
      error: 'No actions to process',
      actionsFound: actions.length,
      timestamp: new Date().toISOString()
    }
  }];
}

// ✅ Datos listos para v2.0 Agentic Loop
console.log(`✅ ${actions.length} actions ready for v2.0 Agentic Loop`);

return [{
  json: {
    success: true,
    actions: actions,
    sessionId: sessionId,
    metadata: metadata,
    timestamp: new Date().toISOString()
  }
}];

// 🤖 CONSTRUIR PAYLOAD v2.0 AGENTIC LOOP
const validationResult = $json;

// Verificar si hay error en la validación
if (!validationResult.success) {
  console.log('❌ Validation failed');
  return [{
    json: {
      success: false,
      error: validationResult.error || 'Validation failed',
      timestamp: new Date().toISOString()
    }
  }];
}

const actions = validationResult.actions || [];
const metadata = validationResult.metadata || {};

console.log(`🤖 Building v2.0 Agentic Loop payload for ${actions.length} actions`);

// 🎯 TRADUCIR ACCIONES A OBJETIVO EN LENGUAJE NATURAL
// Gemini v2.0 trabaja con goals en lenguaje natural, NO con JSON de acciones

let goal = '';

// Construir el goal desde las acciones capturadas
if (actions.length > 0) {
  const firstAction = actions[0];

  // Determinar el objetivo basado en las acciones
  if (firstAction.type === 'navigation' || firstAction.type === 'navigate') {
    goal = `Navega a ${firstAction.url || firstAction.href}`;
  } else {
    goal = `Ejecuta las siguientes acciones web: ${actions.map((a, i) => `${i + 1}. ${a.type} ${a.selector || a.url || ''}`).join(', ')}`;
  }

  // Agregar acciones subsecuentes
  for (let i = 1; i < actions.length; i++) {
    const action = actions[i];

    if (action.type === 'click' || action.type === 'button_click') {
      goal += ', luego haz click en el elemento ' + (action.selector || action.element);
    } else if (action.type === 'input' || action.type === 'type') {
      goal += ', luego escribe ' + (action.value || action.text) + ' en el campo ' + action.selector;
    } else if (action.type === 'wait') {
      goal += ', luego espera ' + (action.seconds || 2) + ' segundos';
    } else if (action.type === 'submit') {
      goal += ', luego envía el formulario';
    }
  }

  goal += '. Captura el resultado final y confirma que la tarea se completó correctamente.';
}

// Si no se pudo construir un goal, usar uno genérico
if (!goal) {
  goal = `Automatiza las siguientes ${actions.length} acciones web y confirma que se completaron: ${JSON.stringify(actions).slice(0, 200)}`;
}

console.log('🎯 Goal construido:', goal);

// 🚀 PAYLOAD v2.0 - FORMATO PARA /agent/run
const v2Payload = {
  goal: goal,
  options: {
    headless: metadata.headless !== undefined ? metadata.headless : false,
    maxIterations: 30,
    verbose: true
  },
  metadata: {
    source: 'n8n-testbuilder-v2',
    sessionId: validationResult.sessionId,
    originalActionsCount: actions.length,
    originalActions: actions,
    timestamp: new Date().toISOString()
  }
};

console.log('✅ v2.0 Agentic Payload ready:', {
  goal: goal.slice(0, 100) + '...',
  actionsCount: actions.length,
  headless: v2Payload.options.headless
});

return [{ json: v2Payload }];

// 🔄 PROCESAR RESPUESTA v2.0 AGENTIC LOOP
const agentResponse = $json;
const originalPayload = $node["Build v2 Agentic Payload"].json;

console.log('🔄 v2.0 Agentic Response received:', {
  success: agentResponse.success,
  iterations: agentResponse.iterations,
  goalCompleted: agentResponse.goalCompleted,
  hasExecutionLog: !!agentResponse.executionLog
});

// Manejar errores
if (!agentResponse.success) {
  console.log('❌ Error en v2.0 Agentic Loop:', agentResponse.error);
  return [{
    json: {
      success: false,
      error: 'Error en ejecución del agente v2.0',
      details: agentResponse.error,
      agentResponse: agentResponse,
      originalGoal: originalPayload.goal,
      timestamp: new Date().toISOString()
    }
  }];
}

// ✅ RESPUESTA EXITOSA
const finalResponse = {
  success: true,
  message: `Agente v2.0 completó el objetivo en ${agentResponse.iterations} iteraciones`,
  agent: {
    version: '2.0-agentic-loop',
    goalCompleted: agentResponse.goalCompleted,
    iterations: agentResponse.iterations,
    executionLog: agentResponse.executionLog || [],
    finalState: agentResponse.finalState || {}
  },
  data: {
    goal: originalPayload.goal,
    originalActions: originalPayload.metadata.originalActions,
    actionsProcessed: originalPayload.metadata.originalActionsCount,
    executionTime: agentResponse.executionTime || 'N/A'
  },
  metadata: {
    source: 'n8n-v2-agentic-pipeline',
    sessionId: originalPayload.metadata.sessionId,
    timestamp: new Date().toISOString(),
    agentResponse: agentResponse
  }
};

console.log('✅ v2.0 Agentic Pipeline completado exitosamente');
console.log(`📊 Iteraciones: ${agentResponse.iterations}`);
console.log(`🎯 Goal completado: ${agentResponse.goalCompleted}`);

return [{
  json: finalResponse
}];
